const Discord = require('discord.js');
const dotenv = require('dotenv');
dotenv.config();

const client = new Discord.Client();

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('message', msg => {
  if (msg.content === '!ban') {
    const userToBan = msg.mentions.users.first();
    if (!userToBan) {
      return msg.reply('Please mention a user to ban!');
    }
    const guild = msg.guild;
    const banMember = guild.members.ban(userToBan);
    banMember.send(`${userToBan.user.username} has been banned from ${guild.name}.`);
    msg.reply('User banned successfully!');
  }
});

client.login(process.env.DISCORD_TOKEN);
```
