```
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
  ifstream file("input.txt");
  if (!file.is_open()) {
    cout << "Error opening file" << endl;
    return 1;
  }

  string word;
  int count = 0;

  while (getline(file, word)) {
    count++;
    if (word == "specific_word") {
      count++;
    }
  }

  file.close();
  cout << "Number of occurrences of specific word: " << count << endl;

  return 0;
}
```
